from collections import deque
graph = {'A':['B','C'],'B':['D'],'C':['D','E'],'D':['F'],'E':['F'],'F':[]}
def bfs(start, goal):
    q = deque([[start]]); seen = {start}
    while q:
        path = q.popleft()
        if path[-1] == goal: return path
        for n in graph[path[-1]]:
            if n not in seen:
                seen.add(n); q.append(path + [n])
print(bfs('A','F'))
